<script>
	import { onMount } from 'svelte';
	import Login from './login/index.svelte';
	import Application from './Application/index.svelte';
	import { Notify, Notifications } from '@rdsslab/svelte-components';
	import { get } from 'svelte/store';
	import { userStore, authEventStore } from './Application/utils/stores.js';
	import {
		isJwtExpiringSoon,
		getJwtExpiresInMinutes,
		logJwtExpiration
	} from './Application/utils/jwtUtils.js';

	/** Instancia usada para emitir notificaciones (el componente `Notify` solo las pinta). */
	const notify = new Notifications();

	let page = $state('login');
	let sessionExpired = $state(false);
	let failedLogins = $state(0);

	// Flag para evitar mostrar el aviso de expiración múltiples veces seguidas
	let tokenExpiryWarningShown = false;
	/** @type {ReturnType<typeof setInterval> | null} */
	let jwtWatcherInterval = null;

	/**
	 * Suscripción reactiva al store de eventos de autenticación.
	 * Detecta errores 401 y muestra la notificación correspondiente.
	 */
	$effect(() => {
		const unsubscribe = authEventStore.subscribe((event) => {
			if (!event) return;

			if (event.type === 'unauthorized') {
				// Reset del store para no repetir el mensaje
				authEventStore.set(null);

				if (page === 'main') {
					sessionExpired = true;
					failedLogins = 0;
				} else {
					// Volver a la pantalla de login
					page = 'login';
				}
			}
		});

		return () => unsubscribe();
	});

	/**
	 * Inicia el watcher periódico que revisa si el JWT está próximo a expirar.
	 * Se ejecuta cada 30 segundos. Muestra alerta si quedan ≤5 minutos, y la cierra
	 * automáticamente después de 2 minutos (duration: 120000 ms).
	 */
	function startJwtWatcher() {
		stopJwtWatcher();
		tokenExpiryWarningShown = false;

		jwtWatcherInterval = setInterval(() => {
			const token = get(userStore).token;

			if (!token) return;

			logJwtExpiration(token);

			const minutesLeft = getJwtExpiresInMinutes(token);

			if (minutesLeft <= 0) {
				if (page === 'main' && !sessionExpired) {
					sessionExpired = true;
					failedLogins = 0;
				}
			} else if (isJwtExpiringSoon(token, 5) && !tokenExpiryWarningShown) {
				tokenExpiryWarningShown = true;

				notify.push({
					message: `⚠️ Your session will expire in approximately ${Math.floor(minutesLeft)} minute${Math.floor(minutesLeft) !== 1 ? 's' : ''}. Save your work.`,
					color: 'warning',
					timeout: 120000 // 2 minutos
				});
			}

			// Resetear el flag cuando el token ya expiró o queda más de 5 min
			if (!isJwtExpiringSoon(token, 5)) {
				tokenExpiryWarningShown = false;
			}
		}, 30000); // Revisa cada 30 segundos
	}

	function stopJwtWatcher() {
		if (jwtWatcherInterval !== null) {
			clearInterval(jwtWatcherInterval);
			jwtWatcherInterval = null;
		}
	}

	onMount(() => {
		return () => stopJwtWatcher();
	});
</script>

<Notify></Notify>

{#if page === 'main'}
	<Application
		onexit={() => {
			stopJwtWatcher();
			page = 'login';
		}}
	/>
	{#if sessionExpired}
		<div class="overlay-container">
			<Login
				isOverlay={true}
				onlogin={(/** @type {{login?: string}} */ login) => {
					if (login && login.login) {
						sessionExpired = false;
						failedLogins = 0;
						startJwtWatcher();
					}
				}}
				onfail={() => {
					failedLogins++;
					if (failedLogins >= 3) {
						sessionExpired = false;
						page = 'login';
						failedLogins = 0;
					}
				}}
			/>
		</div>
	{/if}
{:else}
	<Login
		onlogin={(/** @type {{login?: string}} */ login) => {
			if (login && login.login) {
				page = 'main';
				startJwtWatcher();
			} else {
				page = 'login';
			}
		}}
	/>
{/if}

<style>
	/*
	 * Bulma declara `.tag.is-light.is-light` pero nunca define el token al que apunta
	 * (`--bulma-light-light-invert-l`). Una clase repetida en un selector compuesto también
	 * se cumple con una sola ocurrencia, así que esa regla -y no `.tag.is-light`- es la que
	 * gana en todo `<span class="tag is-light">`: columna Status de Tasks, Stopped de bots,
	 * etiquetas de Logs/Audit, etc.
	 *
	 * Con el token sin definir, `color` queda invalido y se hereda; dentro de una celda de
	 * tabla eso es `--bulma-text-strong`, que en dark theme esta al 93% de luminosidad:
	 * texto blanco sobre el chip casi blanco. En light theme esta al 21% y por eso el
	 * fallo solo se ve en dark mode.
	 *
	 * Definir el token que falta devuelve el color que Bulma pretendia, sin pelear por
	 * especificidad ni depender del orden en que se carguen las hojas de estilo.
	 */
	:global(:root) {
		--bulma-light-light-invert-l: var(--bulma-light-invert-l);
	}

	.overlay-container {
		position: absolute;
		top: 0;
		left: 0;
		width: 100%;
		height: 100%;
		z-index: 9999;
	}
</style>
