<script>
	import { getErrorMessage } from '../../utils/errors.js';
	import uFetch from '@rdsslab/uFetch';
	import { isNewApp, mergeSourceOverwrite } from '../../utils/utils.js';
	import { defaultApp } from '../../utils/static_values.js';
	import SaveDeploy from '../common/saveDeploy.svelte';
	import TextAreaWidget from '../common/textArea.svelte';
	import { url_paths } from '../../utils/paths.js';
	import { userStore } from '../../utils/stores.js';
	import {
		GetApp as GetAppRequest,
		GetAppBackup,
		RestoreAppBackup,
		GetAppVars,
		UpsertAppVar
	} from '../../utils/request.js';
	import { Notifications, Input, EditorCode } from '@rdsslab/svelte-components';

	let notify = new Notifications();
	let uf = new uFetch();

	/** @type {Record<string, unknown>} */
	let uploaded_file = {};
	/**
	 * @type {{idapp?: number|string, onsavedeploy?: (app: import('../../../types/models.js').AppRow) => void}}
	 */
	let { idapp = $bindable(), onsavedeploy = () => {} } = $props();
	let deploying = $state({ show: false, message: '', error: false });
	/** @type {import('../../../types/models.js').AppRow} */
	let app = $state({ app: '', enabled: false, description: '' });

	// ── Password recovery configuration (system app only, prd environment) ──
	/** @type {Array<import('../../../types/models.js').AppVarRow>} */
	let recoveryVars = $state([]);
	/** @type {{emailTransport: string, emailFrom: string, telegramToken: string, emailEnabled: boolean, telegramEnabled: boolean}} */
	let recoveryForm = $state({
		emailTransport: '',
		emailFrom: '',
		telegramToken: '',
		emailEnabled: false,
		telegramEnabled: false
	});
	/** @type {string|number|null} */
	let lastLoadedIdapp = $state(null);

	const RECOVERY_VAR_NAMES = [
		'$_VAR_EMAIL_TRANSPORT',
		'$_VAR_EMAIL_FROM',
		'$_VAR_TELEGRAM_TOKEN',
		'$_VAR_RESET_EMAIL_ENABLED',
		'$_VAR_RESET_TELEGRAM_ENABLED'
	];

	const RECOVERY_TRANSPORT_EXAMPLE = `{
  "host": "smtp.example.com",
  "port": 587,
  "secure": false,
  "auth": {
    "user": "user@example.com",
    "pass": "your-password"
  }
}`;

	$effect(() => {
		// Guardamos el valor actual de idapp para evitar race conditions
		const idActual = idapp;

		if (isNewApp(idActual)) {
			app = mergeSourceOverwrite(defaultApp, {});
			console.log('Resetear variables'); // Quitamos la referencia a `app` del log
		} else {
			console.log('Cargar datos de la app');

			GetApp();
		}
	});

	// Carga las AppVars de recuperación cuando la app es "system" (environment prd).
	$effect(() => {
		const appName = app?.app;
		if (appName === 'system' && idapp && idapp !== lastLoadedIdapp) {
			lastLoadedIdapp = idapp;
			loadRecoveryVars();
		} else if (appName !== 'system') {
			lastLoadedIdapp = null;
			recoveryVars = [];
			recoveryForm = {
				emailTransport: '',
				emailFrom: '',
				telegramToken: '',
				emailEnabled: false,
				telegramEnabled: false
			};
		}
	});

	/**
	 * Carga las AppVars de recuperación de la app system para el environment prd.
	 * Si no existen, las inicializa vacías para que el usuario las complete.
	 */
	async function loadRecoveryVars() {
		if (!idapp) return;
		try {
			let rows = await GetAppVars(idapp);
			if (!Array.isArray(rows)) rows = [];
			let prdVars = rows.filter(
				(/** @type {import('../../../types/models.js').AppVarRow} */ r) =>
					r.environment === 'prd'
			);

			recoveryVars = RECOVERY_VAR_NAMES.map((name) => {
				let existing = prdVars.find(
					(/** @type {import('../../../types/models.js').AppVarRow} */ r) =>
						r.name === name
				);
				if (existing) return { ...existing };
				return {
					idapp: idapp,
					name: name,
					value: '',
					environment: 'prd',
					type: name === '$_VAR_EMAIL_TRANSPORT' ? 'json' : 'string',
					enabled: true
				};
			});

			let t = recoveryVars.find((r) => r.name === '$_VAR_EMAIL_TRANSPORT');
			let f = recoveryVars.find((r) => r.name === '$_VAR_EMAIL_FROM');
			let tk = recoveryVars.find((r) => r.name === '$_VAR_TELEGRAM_TOKEN');
			let fe = recoveryVars.find((r) => r.name === '$_VAR_RESET_EMAIL_ENABLED');
			let te = recoveryVars.find((r) => r.name === '$_VAR_RESET_TELEGRAM_ENABLED');

			recoveryForm = {
				emailTransport: t?.value ?? '',
				emailFrom: f?.value ?? '',
				telegramToken: tk?.value ?? '',
				emailEnabled: fe?.value === 'true',
				telegramEnabled: te?.value === 'true'
			};
		} catch (error) {
			console.error('loadRecoveryVars:', error);
		}
	}

	/**
	 * Sincroniza recoveryVars desde recoveryForm antes de guardar.
	 * Mapea cada AppVar de recuperación al valor del formulario.
	 */
	function syncRecoveryVarsFromForm() {
		recoveryVars = recoveryVars.map((rv) => {
			switch (rv.name) {
				case '$_VAR_EMAIL_TRANSPORT':
					rv.value = recoveryForm.emailTransport;
					rv.type = 'json';
					break;
				case '$_VAR_EMAIL_FROM':
					rv.value = recoveryForm.emailFrom;
					rv.type = 'string';
					break;
				case '$_VAR_TELEGRAM_TOKEN':
					rv.value = recoveryForm.telegramToken;
					rv.type = 'string';
					break;
				case '$_VAR_RESET_EMAIL_ENABLED':
					rv.value = recoveryForm.emailEnabled ? 'true' : 'false';
					rv.type = 'string';
					break;
				case '$_VAR_RESET_TELEGRAM_ENABLED':
					rv.value = recoveryForm.telegramEnabled ? 'true' : 'false';
					rv.type = 'string';
					break;
			}
			return rv;
		});
	}

	/**
	 * Guarda todas las AppVars de recuperación (environment prd).
	 * Se invoca al presionar el botón principal "Save & deploy".
	 */
	async function saveAllRecoveryVars() {
		if (!idapp) return;
		syncRecoveryVarsFromForm();

		let saved = 0;
		let errors = 0;
		for (const rv of recoveryVars) {
			let appvar = { ...rv };
			try {
				let result = await UpsertAppVar(appvar, $userStore.token);
				if (result && result.idvar) {
					appvar.idvar = result.idvar;
					saved++;
				} else {
					errors++;
					notify.push({
						message: `Error saving ${rv.name}: ${result?.message || result?.error || 'Unknown error'}`,
						color: 'danger'
					});
				}
			} catch (error) {
				errors++;
				console.error(error);
				notify.push({
					message: `Error saving ${rv.name}: ${getErrorMessage(error)}`,
					color: 'danger'
				});
			}
		}

		if (errors === 0 && saved > 0) {
			notify.push({ message: 'Password recovery variables saved successfully.', color: 'success' });
		} else if (errors > 0) {
			notify.push({ message: `${saved} saved, ${errors} failed.`, color: 'warning' });
		}
	}

	// IMPORTANTE: NUNCA LEAS `app` DENTRO DE ESTE EFECTO
	// Cualquier lectura de `app` haría que el efecto se active cuando `app` cambie

	// Función que valida el input para permitir solo letras y números
	/**
	 * @param {KeyboardEvent} event
	 */
	function validateInput(event) {
		const tecla = event.key; // obtiene la tecla presionada
		const permitido = /^[a-zA-Z0-9]$/; // solo letras y números

		// Si la tecla NO coincide con la expresión permitida...
		if (!permitido.test(tecla)) {
			event.preventDefault(); // cancela la entrada del carácter
		}
	}

	function clearDataVars() {
		console.log('clearDataVars No hay datos');
	}

	async function SaveApp() {
		try {
			let request = await uf.post({
				url: url_paths.app,
				data: $state.snapshot(app)
			});

			let response = await request.json();

			if (request.status == 200 && response) {
				app = { ...response };
				deploying.show = false;
				//console.log(response);
			} else {
				deploying.error = true;
				deploying.message = `Error: ${response.message || request.statusText}`;
				// No se obtuvieron datos
				clearDataVars();
			}
		} catch (error) {
			console.error(error);
			deploying.error = true;
			deploying.message = `Error: ${getErrorMessage(error)}`;
		} finally {
			onsavedeploy(app);
		}
	}

	async function GetApp() {
		try {
			let response = await GetAppRequest(
				/** @type {string|number} */ (idapp ?? ''),
				$userStore.token
			);

			if (response) {
				app = { ...response };

				console.log(response);
			} else {
				// No se obtuvieron datos
				clearDataVars();
			}
		} catch (error) {
			console.error(error);
		}
	}

	// Alternativamente, también podemos limpiar pegados (Ctrl+V)
	/**
	 * @param {Event} e
	 */
	function clearInput(e) {
		const input = /** @type {HTMLInputElement} */ (e.target);
		input.value = input.value.replace(/[^a-zA-Z0-9]/g, '');
	}

	// Genera una clave JWT nueva (UUID v4). crypto.randomUUID solo está
	// disponible en contextos seguros (HTTPS/localhost); se usa un fallback
	// para servidores servidos por HTTP.
	function generateJwtKey() {
		if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
			return crypto.randomUUID();
		}

		return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
			const r = (Math.random() * 16) | 0;
			const v = c === 'x' ? r : (r & 0x3) | 0x8;
			return v.toString(16);
		});
	}
</script>

{#snippet backup_restore_app()}
	{#if $userStore}
		<div class="field has-addons">
			<p class="control">
				<button class="button is-small is-info is-dark">
					<span> Application: {app.app} </span>
				</button>
			</p>
			<p class="control file">
				<input
					class="input is-small"
					type="file"
					accept=".json"
					onchange={(/** @type {Event} */ event) => {
						const input = /** @type {HTMLInputElement} */ (event.target);
						const selectedFile = input?.files?.[0]; // Obten el primer archivo seleccionado

						if (!selectedFile) {
							//alert('Por favor, selecciona un archivo JSON válido.');
							notify.push({ message: 'Invalid JSON file', color: 'warning' });
							return;
						}

						const reader = new FileReader();

						// Escucha el evento 'load' que se dispara cuando se ha leído el archivo
						reader.onload = (event) => {
							const fileContent = /** @type {string} */ (event.target?.result); // Aquí tienes el contenido del archivo

							try {
								uploaded_file = JSON.parse(fileContent);
							} catch (error) {
								uploaded_file = {};
								notify.push({ message: getErrorMessage(error), color: 'danger' });
								console.error('Error al analizar el archivo JSON:', error);
							}
						};

						// Lee el contenido del archivo como texto
						reader.readAsText(selectedFile);
					}}
				/>
			</p>

			<p class="control">
				<button
					class="button is-small"
					onclick={async () => {
						//alert('Ha hecho click');

						//showAppData([uploaded_file]);

						if (!uploaded_file.idapp) {
							alert('Invalid File app data');
						} else if (
							uploaded_file.idapp == app.idapp &&
							confirm('This action will replace existing data. ')
						) {
							// TODO: Aquí puedes realizar acciones con los datos JSON, por ejemplo, mostrarlos en la página.
							let data_return = await RestoreAppBackup(uploaded_file);

							if (data_return.idapp == app.idapp) {
								idapp = data_return.idapp;
								notify.push({
									message: 'App restored',
									color: 'success'
								});
							} else {
								notify.push({
									message: 'App not restored',
									color: 'danger'
								});
							}
						} else if (
							uploaded_file.idapp != app.idapp &&
							confirm(
								'The file does not correspond to the same application. Do you want to create a new one?'
							)
						) {
							let data_return = await RestoreAppBackup(uploaded_file);

							if (data_return.idapp) {
								idapp = data_return.idapp;
								notify.push({
									message: 'New app created',
									color: 'success'
								});
							} else {
								notify.push({
									message: 'App not restored',
									color: 'danger'
								});
							}
						}
						// Emite el evento onsavedeploy para notificar que se ha guardado/desplegado la app
						onsavedeploy(app);
					}}
				>
					<span class="icon is-small">
						<i class="fa-solid fa-upload"></i>
					</span>

					<span> Restore </span>
				</button>
			</p>
			<p class="control">
				<button
					class="button is-small"
					onclick={async () => {
						const now = new Date();
						const year = now.getFullYear();
						const month = String(now.getMonth() + 1).padStart(2, '0'); // Sumamos 1 al mes ya que en JavaScript los meses van de 0 a 11
						const day = String(now.getDate()).padStart(2, '0');
						const hours = String(now.getHours()).padStart(2, '0');
						const minutes = String(now.getMinutes()).padStart(2, '0');

						//const formattedDateTime = `${year}-${month}-${day} ${hours}:${minutes}`;
						let app_json = await GetAppBackup(
							/** @type {string|number} */ (app.idapp ?? ''),
							$userStore.token
						);
						// Convertir el objeto JSON a una cadena
						const jsonString = JSON.stringify(app_json, null, 2);

						// Crear un Blob con el contenido JSON
						const blob = new Blob([jsonString], { type: 'application/json' });

						// Crear una URL para el Blob
						const url = window.URL.createObjectURL(blob);

						// Crear un enlace para descargar el JSON
						const a = document.createElement('a');
						a.href = url;
						a.download = `app_${app.app}_${year}${month}${day}_${hours}${minutes}.json`;

						// Simular un clic en el enlace para iniciar la descarga
						a.click();

						// Liberar recursos
						window.URL.revokeObjectURL(url);
					}}
				>
					<span class="icon is-small">
						<i class="fa-solid fa-download"></i>
					</span>

					<span> Backup </span>
				</button>
			</p>
		</div>
	{/if}
{/snippet}

<div class="">
	<SaveDeploy
		bind:deploying
		left={[backup_restore_app]}
		onsavedeploy={async () => {
			await SaveApp();
			if (app.app === 'system') {
				await saveAllRecoveryVars();
			}
		}}
		oncancel={() => {
			//	alert('No');
		}}
	></SaveDeploy>

	<div class="columns">
		<div class="column">
			<div class="field has-addons">
				<p class="control">
					<!-- svelte-ignore a11y_missing_attribute -->
					<a class="button is-static is-small"> Application </a>
				</p>
				<p class="control">
					{#if app}
						<input
							class="input is-small"
							type="text"
							placeholder="Application name"
							bind:value={app.app}
							onkeypress={(event) => {
								validateInput(event);
							}}
							oninput={(event) => {
								clearInput(event);
							}}
						/>
					{/if}
				</p>
			</div>
		</div>
		<div class="column">
			<div class="field has-addons">
				<p class="control">
					<!-- svelte-ignore a11y_missing_attribute -->
					<a class="button is-static is-small"> UUID App </a>
				</p>
				<p class="control">
					{#if app}
						<input
							class="input is-small"
							size="50"
							type="text"
							readonly
							placeholder="UUID App"
							value={app.idapp}
						/>
					{/if}
				</p>
			</div>
		</div>
		<div class="column">
			<div class="field has-addons">
				<p class="control">
					<!-- svelte-ignore a11y_missing_attribute -->
					<a class="button is-static is-small"> JWT Key </a>
				</p>
				<p class="control is-expanded">
					{#if app}
						<input
							class="input is-small"
							type="text"
							readonly
							placeholder="JWT Key"
							value={app.jwt_key}
							title="Signing key used to mint the API keys of this application."
						/>
					{/if}
				</p>
				<p class="control">
					<button
						class="button is-small"
						title="Generate a new JWT signing key"
						onclick={() => {
							if (
								!confirm(
									'Regenerating the JWT key will invalidate all current API tokens signed with it. Existing tokens will stop working and must be regenerated. Do you want to continue?'
								)
							) {
								return;
							}

							app.jwt_key = generateJwtKey();
						}}
					>
						<span class="icon is-small">
							<i class="fa-solid fa-rotate"></i>
						</span>
						<span> Generate </span>
					</button>
				</p>
			</div>
		</div>
		<div class="column">
			<div class="field has-addons">
				<p class="control">
					<!-- svelte-ignore a11y_missing_attribute -->
					<a class="button is-static is-small"> Enabled </a>
				</p>
				<p class="control">
					{#if app}
						<input
							type="button"
							bind:value={app.enabled}
							class={app.enabled
								? 'button is-success is-selected is-small'
								: 'button is-danger is-small'}
							onclick={() => {
								app.enabled = !app.enabled;
							}}
						/>
					{/if}
				</p>
			</div>
		</div>
	</div>

	<TextAreaWidget label="Description" bind:value={app.description}></TextAreaWidget>

	{#if app.app === 'system'}
		<div class="field">
			<label class="label">Password Recovery Configuration</label>
			<p class="help">
				OTP-based password recovery via email or Telegram. Only visible for the "system"
				application. Environment: prd. Saved on "Save & deploy".
			</p>
		</div>

		<div class="field">
			<label class="label">SMTP Transport (JSON)</label>
			<p class="control is-expanded">
				{#snippet recoveryLeft()}
					<span>SMTP Transport</span>
				{/snippet}
				{#snippet recoveryRight()}
					<span>application/json</span>
				{/snippet}
				<EditorCode
					left={recoveryLeft}
					right={recoveryRight}
					bind:code={recoveryForm.emailTransport}
					lang="json"
					isReadOnly={false}
					showFormat={true}
				></EditorCode>
			</p>
			<p class="help">
				JSON configuration for nodemailer SMTP transport. The backend reads <code
					>$_VAR_EMAIL_TRANSPORT</code
				>.
			</p>
		</div>

		<div class="field">
			<label class="label">Example SMTP Transport JSON</label>
			<div class="control">
				<pre
					style="background:#f5f5f5;padding:10px;border:1px solid #ddd;font-size:12px;overflow:auto;white-space:pre-wrap;">{RECOVERY_TRANSPORT_EXAMPLE}</pre>
			</div>
			<p class="help">Paste your SMTP transport configuration as JSON above.</p>
		</div>

		<div class="field has-addons">
			<p class="control is-expanded">
				<Input
					label="Email From"
					bind:value={recoveryForm.emailFrom}
					type="text"
					placeholder="sender@example.com"
				></Input>
			</p>
		</div>

		<div class="field has-addons">
			<p class="control is-expanded">
				<Input
					label="Telegram Bot Token"
					bind:value={recoveryForm.telegramToken}
					type="password"
					placeholder="Bot token from @BotFather"
				></Input>
			</p>
		</div>

		<div class="field has-addons">
			<p class="control">
				<label class="label">Email Channel Enabled</label>
			</p>
			<p class="control">
				<input
					type="button"
					value={recoveryForm.emailEnabled ? 'On' : 'Off'}
					class={recoveryForm.emailEnabled
						? 'button is-success is-selected is-small'
						: 'button is-danger is-small'}
					onclick={() => {
						recoveryForm.emailEnabled = !recoveryForm.emailEnabled;
					}}
				/>
			</p>
		</div>

		<div class="field has-addons">
			<p class="control">
				<label class="label">Telegram Channel Enabled</label>
			</p>
			<p class="control">
				<input
					type="button"
					value={recoveryForm.telegramEnabled ? 'On' : 'Off'}
					class={recoveryForm.telegramEnabled
						? 'button is-success is-selected is-small'
						: 'button is-danger is-small'}
					onclick={() => {
						recoveryForm.telegramEnabled = !recoveryForm.telegramEnabled;
					}}
				/>
			</p>
		</div>
	{/if}
</div>
