"use strict";

const regexIsAbsolute = /^[a-zA-Z][a-zA-Z\d+\-.]*:/;
const DEFAULT_TIMEOUT_CONFIG = {
  timeout: 3600000,
  headersTimeout: 3600000,
  bodyTimeout: undefined,
  socketTimeout: undefined,
};
const NODE_TIMEOUT_ERROR_CODE_TO_CONFIG_KEY = {
  UND_ERR_HEADERS_TIMEOUT: "headersTimeout",
  UND_ERR_BODY_TIMEOUT: "bodyTimeout",
  UND_ERR_SOCKET: "socketTimeout",
};

const isNodeRuntime = () =>
  typeof process !== "undefined" &&
  process.versions != null &&
  process.versions.node != null;

/**
 * Dynamically selects fetch from the environment (browser / node)
 * to avoid crashes if a polyfill is loaded later.
 */
const getFetch = () => {
  if (typeof window !== "undefined" && typeof window.fetch === "function") {
    return window.fetch.bind(window);
  }
  if (typeof globalThis !== "undefined" && typeof globalThis.fetch === "function") {
    return globalThis.fetch.bind(globalThis);
  }
  throw new Error("fetch is not defined. Please verify your environment or add a polyfill.");
};

const validMethods = new Set([
  "GET",
  "POST",
  "PUT",
  "PATCH",
  "DELETE",
  "HEAD",
  "OPTIONS",
  "CONNECT",
  "TRACE",
  "QUERY",
]);

const resolveBatchItems = (items) => {
  if (Array.isArray(items)) {
    return { list: items, sendAs: "data" };
  }

  if (items !== null && typeof items === "object") {
    const hasData = Object.prototype.hasOwnProperty.call(items, "data");
    const hasBody = Object.prototype.hasOwnProperty.call(items, "body");

    if (hasData && hasBody) {
      throw new Error("uFetch.batch(): 'items' cannot define both 'data' and 'body' at the same time. Use only one.");
    }
    if (hasData) {
      if (!Array.isArray(items.data)) {
        throw new Error("uFetch.batch(): 'items.data' must be an array.");
      }
      return { list: items.data, sendAs: "data" };
    }
    if (hasBody) {
      if (!Array.isArray(items.body)) {
        throw new Error("uFetch.batch(): 'items.body' must be an array.");
      }
      return { list: items.body, sendAs: "body" };
    }
  }

  throw new Error("uFetch.batch(): 'items' must be an array, or an object containing a 'data' or 'body' array property.");
};

const defaultResponseParser = async (response) => {
  if (response.status === 204) {
    return null;
  }
  const contentType = response.headers.get("content-type");
  if (contentType && contentType.includes("application/json")) {
    return await response.json();
  }
  const text = await response.text();
  try {
    return JSON.parse(text);
  } catch (err) {
    return text;
  }
};

/**
 * uFetch class: Universal and AI-friendly wrapper for HTTP requests (based on 'fetch').
 * Provides tools to automatically handle relative/absolute URLs, JSON bodies,
 * Authorization headers, Query parameters and abstracts the environment context (Browser vs NodeJS).
 */
class uFetch {
  /**
   * Initializes the HTTP client instance, mirroring the `fetch(resource, options)` shape.
   * @param {string} [url=undefined] - (Optional) Default base URL to use in requests.
   * @param {{redirect_in_unauthorized?: string, timeout?: number, headersTimeout?: number, bodyTimeout?: number, socketTimeout?: number}} [options={}] - (Optional) Instance configuration.
   * @param {string} [options.redirect_in_unauthorized] - Route or URL to automatically redirect the client in case of 401 error (Only in Browser environment with window).
   * @param {{username: string, password: string}} [options.basicAuthentication] - Basic Auth credentials to configure at construction time.
   * @param {string} [options.bearerAuthentication] - Bearer token to configure at construction time. Takes precedence over `basicAuthentication` if both are provided.
   * @param {number} [options.timeout] - Default request timeout in milliseconds. Defaults to 1 hour.
   * @param {number} [options.headersTimeout] - Undici headers timeout (Node.js only).
   * @param {number} [options.bodyTimeout] - Undici body timeout (Node.js only).
   * @param {number} [options.socketTimeout] - Undici socket timeout (Node.js only).
   */
  constructor(url = undefined, options = undefined, legacyTimeoutOptions = undefined) {
    let redirect_in_unauthorized;
    let basicAuthentication;
    let bearerAuthentication;
    let timeoutOptions;

    // BC shim for the deprecated positional signature: (url, redirect_in_unauthorized, timeoutOptions)
    if (typeof options === "string" || legacyTimeoutOptions !== undefined) {
      console.warn(
        "DeprecationWarning: new uFetch(url, redirect_in_unauthorized, timeoutOptions) is deprecated. " +
        "Use new uFetch(url, options) instead, where options = { redirect_in_unauthorized, timeout, headersTimeout, bodyTimeout, socketTimeout }."
      );
      redirect_in_unauthorized = options;
      timeoutOptions = legacyTimeoutOptions || {};
    } else {
      const { redirect_in_unauthorized: ru, basicAuthentication: ba, bearerAuthentication: bea, ...rest } = options || {};
      redirect_in_unauthorized = ru;
      basicAuthentication = ba;
      bearerAuthentication = bea;
      timeoutOptions = rest;
    }

    this._redirect_in_unauthorized_internal = redirect_in_unauthorized;
    this._basic_authentication = undefined;
    this._bearer_authentication = undefined;
    this._url = url;
    this._defaultHeaders = new Map();
    this._timeoutConfig = { ...DEFAULT_TIMEOUT_CONFIG, ...timeoutOptions };
    this._undiciDispatcher = undefined;

    if (basicAuthentication && basicAuthentication.username && basicAuthentication.password) {
      this.setBasicAuthorization(basicAuthentication.username, basicAuthentication.password);
    }
    if (bearerAuthentication) {
      this.setBearerAuthorization(bearerAuthentication);
    }

    this._refreshUndiciDispatcher();

    if (typeof AbortController !== "undefined") {
      this._abortController = new AbortController();
    }
  }

  /**
   * Immediately cancels all in-progress requests generated by this instance
   * that do not have an explicitly overridden AbortSignal. 
   * Internally resets to a new controller to support immediate subsequent requests.
   * @param {any} [reason] - Reason, message, or exception returned in the promise rejection catch (e.g., AbortError).
   */
  abort(reason) {
    if (this._abortController) {
      this._abortController.abort(reason);
      this._abortController = new AbortController();
    }
  }

  /**
   * Configures Basic Auth credentials at the client instance level, injecting them into 'Authorization'.
   * @param {string} username - Plain text username.
   * @param {string} password - Plain text password.
   * @returns {uFetch} Returns the current instance enabling context chaining.
   */
  setBasicAuthorization(username, password) {
    if (
      !username ||
      !password ||
      typeof username !== "string" ||
      typeof password !== "string"
    ) {
      this._basic_authentication = undefined;
      return this;
    }

    const credentials = `${username}:${password}`;
    const base64 =
      typeof Buffer !== "undefined"
        ? Buffer.from(credentials).toString("base64")
        : btoa(credentials);

    this._basic_authentication = `Basic ${base64}`;
    this._bearer_authentication = undefined;
    return this;
  }

  /**
   * @deprecated Use setBasicAuthorization() instead.
   */
  SetBasicAuthorization(username, password) {
    console.warn("DeprecationWarning: uFetch.SetBasicAuthorization() is deprecated. Use uFetch.setBasicAuthorization() instead.");
    return this.setBasicAuthorization(username, password);
  }

  /**
   * @deprecated Use clearAuthorizationHeader() instead.
   */
  ClearAuthorizationHeader() {
    console.warn("DeprecationWarning: uFetch.ClearAuthorizationHeader() is deprecated. Use uFetch.clearAuthorizationHeader() instead.");
    this.clearAuthorizationHeader();
  }

  /**
   * Explicitly completely clears and revokes all authorization headers 
   * stored in memory for this instance (both Basic and Bearer auth).
   */
  clearAuthorizationHeader() {
    this._basic_authentication = undefined;
    this._bearer_authentication = undefined;
  }

  /**
   * Alias for setBasicAuthorization for convenience.
   * @param {string} user 
   * @param {string} password 
   * @returns {uFetch}
   */
  setBasicAuthentication(user, password) {
    return this.setBasicAuthorization(user, password);
  }

  /**
   * @deprecated Use setBasicAuthentication() instead.
   */
  SetBasicAuthentication(user, password) {
    console.warn("DeprecationWarning: uFetch.SetBasicAuthentication() is deprecated. Use uFetch.setBasicAuthentication() instead.");
    return this.setBasicAuthentication(user, password);
  }

  /**
   * Configures a Bearer token for the 'Authorization' header at the instance level.
   * Its activation will explicitly deactivate/overwrite any previously persisted Basic credential.
   * @param {string} key - Token key (e.g., a pure JWT or Access Hash).
   * @returns {uFetch} Returns the class for context chaining.
   */
  setBearerAuthorization(key) {
    if (typeof key === "string" && key.trim() !== "") {
      this._bearer_authentication = `Bearer ${key.trim()}`;
      this._basic_authentication = undefined;
      return this;
    }
    if (key != null && key !== "") {
      console.warn(
        "uFetch.setBearerAuthorization: se esperaba un string y se recibió " +
          (key === null ? "null" : typeof key === "object" ? (key.constructor && key.constructor.name ? key.constructor.name : "Object") : typeof key) +
          "; no se envía Authorization."
      );
    }
    this._bearer_authentication = undefined;
    this._basic_authentication = undefined;
    return this;
  }

  /**
   * Adds a global, permanent, and persistent header that will be attached to all future
   * peticiones invocadas por este objeto `uFetch`.
   * @param {string} key - Name of the HTTP header block (e.g. 'Application-Context').
   * @param {string} value - String value of the header.
   */
  addHeader(key, value) {
    if (typeof value === "object" && value !== null && !(typeof Headers !== "undefined" && value instanceof Headers) && !(typeof Map !== "undefined" && value instanceof Map)) {
      console.warn("uFetch.addHeader: el valor para '" + key + "' es un objeto; se convertirá a texto.");
    }
    this._defaultHeaders.set(key, value);
  }

  /**
   * Configures the default timeout behavior for all future requests.
   * @param {{timeout?: number, headersTimeout?: number, bodyTimeout?: number, socketTimeout?: number}} [opts={}] - Timeout values in milliseconds.
   * @returns {uFetch}
   */
  setTimeouts(opts = {}) {
    this._timeoutConfig = { ...this._timeoutConfig, ...opts };
    this._refreshUndiciDispatcher();
    return this;
  }

  /**
   * Convenience helper for browser-style abort timeouts.
   * @param {number} timeout - Timeout in milliseconds.
   * @returns {uFetch}
   */
  setAbortTimeout(timeout) {
    return this.setTimeouts({ timeout });
  }

  _refreshUndiciDispatcher() {
    if (!isNodeRuntime()) {
      return;
    }

    this._destroyUndiciDispatcher();

    try {
      const { Agent } = require("undici");
      const { headersTimeout, bodyTimeout, socketTimeout } = this._timeoutConfig;
      const dispatcherOptions = {};

      if (Number.isFinite(headersTimeout)) {
        dispatcherOptions.headersTimeout = headersTimeout;
      }
      if (Number.isFinite(bodyTimeout)) {
        dispatcherOptions.bodyTimeout = bodyTimeout;
      }
      if (Number.isFinite(socketTimeout)) {
        dispatcherOptions.socketTimeout = socketTimeout;
      }

      this._undiciDispatcher = new Agent(dispatcherOptions);
    } catch (err) {
      this._undiciDispatcher = undefined;
    }
  }

  _destroyUndiciDispatcher() {
    if (!this._undiciDispatcher) {
      return;
    }

    try {
      if (typeof this._undiciDispatcher.destroy === "function") {
        this._undiciDispatcher.destroy();
      } else if (typeof this._undiciDispatcher.close === "function") {
        this._undiciDispatcher.close();
      }
    } catch (err) {
      // Ignore dispatcher teardown failures; a fresh dispatcher will be created when possible.
    }

    this._undiciDispatcher = undefined;
  }

  _mergeSignals(signals = []) {
    const activeSignals = signals.filter(Boolean);

    if (activeSignals.length === 0 || typeof AbortController === "undefined") {
      return {
        signal: undefined,
        cleanup: () => {},
      };
    }

    if (activeSignals.length === 1) {
      return {
        signal: activeSignals[0],
        cleanup: () => {},
      };
    }

    const controller = new AbortController();
    const listeners = [];

    const abortFromSignal = (sourceSignal) => {
      if (controller.signal.aborted) {
        return;
      }

      const reason = sourceSignal && "reason" in sourceSignal ? sourceSignal.reason : undefined;
      controller.abort(reason);
    };

    for (const sourceSignal of activeSignals) {
      if (sourceSignal.aborted) {
        abortFromSignal(sourceSignal);
        return {
          signal: controller.signal,
          cleanup: () => {
            for (const removeListener of listeners) {
              removeListener();
            }
          },
        };
      }

      const onAbort = () => abortFromSignal(sourceSignal);
      sourceSignal.addEventListener("abort", onAbort, { once: true });
      listeners.push(() => sourceSignal.removeEventListener("abort", onAbort));
    }

    return {
      signal: controller.signal,
      cleanup: () => {
        for (const removeListener of listeners) {
          removeListener();
        }
      },
    };
  }

  _applyTimeout(signal, timeoutMs) {
    if (
      typeof AbortController === "undefined" ||
      !Number.isFinite(timeoutMs) ||
      timeoutMs < 0
    ) {
      return {
        signal,
        cleanup: () => {},
        didTimeout: () => false,
      };
    }

    const timeoutController = new AbortController();
    let didTimeout = false;
    const timer = setTimeout(() => {
      didTimeout = true;
      timeoutController.abort();
    }, timeoutMs);

    const mergedSignal = this._mergeSignals([signal, timeoutController.signal]);

    return {
      signal: mergedSignal.signal,
      cleanup: () => {
        clearTimeout(timer);
        mergedSignal.cleanup();
      },
      didTimeout: () => didTimeout,
    };
  }

  _getTimeoutMessageDuration(err, requestTimeoutMs) {
    const timeoutConfigKey = err && err.code ? NODE_TIMEOUT_ERROR_CODE_TO_CONFIG_KEY[err.code] : undefined;

    if (timeoutConfigKey && Number.isFinite(this._timeoutConfig[timeoutConfigKey])) {
      return this._timeoutConfig[timeoutConfigKey];
    }

    if (Number.isFinite(requestTimeoutMs)) {
      return requestTimeoutMs;
    }

    if (Number.isFinite(this._timeoutConfig.timeout)) {
      return this._timeoutConfig.timeout;
    }

    return undefined;
  }

  _setErrorMessage(err, message) {
    try {
      err.message = message;
    } catch (assignError) {
      Object.defineProperty(err, "message", {
        configurable: true,
        value: message,
      });
    }
  }

  _addAuthorizationHeader(headers) {
    if (this._basic_authentication) {
      headers.set("Authorization", this._basic_authentication);
    } else if (this._bearer_authentication) {
      headers.set("Authorization", this._bearer_authentication);
    } else if (headers.get('Authorization')) {
      headers.set("Authorization", headers.get('Authorization'));
    } else {
      headers.delete("Authorization");
    }
  }

  _normalizeHeaders(headers = {}, data = undefined) {
    if (headers == null) {
      headers = {};
    }

    const h = new Headers();

    // Helper to add headers from various sources
    const addFn = (v, k) => {
      if (typeof v === "object" && v !== null && !(typeof Headers !== "undefined" && v instanceof Headers) && !(typeof Map !== "undefined" && v instanceof Map)) {
        console.warn("uFetch: valor de header '" + k + "' es un objeto; se convertirá a texto.");
      }
      h.append(k, v);
    };

    if (headers instanceof Headers || headers instanceof Map) {
      headers.forEach(addFn);
    } else {
      // iterate over object
      for (const [k, v] of Object.entries(headers)) {
        if (typeof v === "object" && v !== null && !(typeof Headers !== "undefined" && v instanceof Headers) && !(typeof Map !== "undefined" && v instanceof Map)) {
          console.warn("uFetch: valor de header '" + k + "' es un objeto; se convertirá a texto.");
        }
        h.append(k, v);
      }
    }

    // agregar headers por defecto
    for (const [k, v] of this._defaultHeaders.entries()) {
      if (typeof v === "object" && v !== null && !(typeof Headers !== "undefined" && v instanceof Headers) && !(typeof Map !== "undefined" && v instanceof Map)) {
        console.warn("uFetch: valor de header '" + k + "' es un objeto; se convertirá a texto.");
      }
      h.set(k, v);
    }

    // auth
    this._addAuthorizationHeader(h);

    if (!h.has("Content-Type")) {
      const isSpecialBody =
        (typeof FormData !== "undefined" && data instanceof FormData) ||
        (typeof Blob !== "undefined" && data instanceof Blob) ||
        (typeof URLSearchParams !== "undefined" && data instanceof URLSearchParams) ||
        (typeof ReadableStream !== "undefined" && data instanceof ReadableStream) ||
        (typeof ArrayBuffer !== "undefined" && data instanceof ArrayBuffer);

      // Only add application/json if data is not special AND not a string
      // strings are strictly treated as raw bodies unless header says otherwise
      if (!isSpecialBody && data != null && typeof data !== "string") {
        h.append("Content-Type", "application/json");
      }
    }

    // Eliminar Content-Length
    h.delete("Content-Length");

    return h;
  }

  _createBody(data) {
    if (data == null) return undefined;

    // casos especiales
    if (
      (typeof FormData !== "undefined" && data instanceof FormData) ||
      (typeof Blob !== "undefined" && data instanceof Blob) ||
      (typeof URLSearchParams !== "undefined" && data instanceof URLSearchParams) ||
      (typeof ReadableStream !== "undefined" && data instanceof ReadableStream) ||
      (typeof ArrayBuffer !== "undefined" && data instanceof ArrayBuffer) ||
      typeof data === "string"
    ) {
      return data;
    }

    // fallback → JSON
    return JSON.stringify(data);
  }

  /**
   * Low-level core engine to execute an asynchronous network request using the Fetch API.
   * Automatically injects Authorization headers and handles smart serialization.
   * 
   * @param {string} url - Final absolute URL, or internal relative path.
   * @param {string} [method="GET"] - HTTP verb in uppercase (GET, POST, PUT, DELETE, PATCH, QUERY, etc).
   * @param {any} [data=undefined] - Parameters sent as a querystring for GET/HEAD/DELETE, or as request body for POST/PUT/PATCH/QUERY (when body is not defined).
   * @param {Object} [headers={}] - Additional dictionary of ephemeral headers living only for this specific transaction.
   * @param {RequestInit & {timeout?: number}} [options={}] - Base object for strict overriding of primitive Fetch options (Credentials, Caching, Mode, custom Signal, etc).
   * @param {any} [body=undefined] - (Optional) Explicit body payload sent in the request body. If set, takes precedence over data for the HTTP body.
   * @param {number} [timeout=undefined] - Optional request-specific timeout in milliseconds.
   * @returns {Promise<Response>} Promise resolving to the Fetch Response object.
   * @throws Exception when asynchronous URL validation fails locally or fetch explicitly fails.
   */
  async request(
    url,
    method = "GET",
    data = undefined,
    headers = {},
    options = {},
    body = undefined,
    timeout = undefined,
  ) {
    method = method.toUpperCase();

    if (!validMethods.has(method)) {
      throw new Error("Invalid method");
    }

    let finalURL = url || this._url;

    if (url && this._url && !regexIsAbsolute.test(url)) {
      try {
        finalURL = new URL(url, this._url).toString();
      } catch (e) {
        // Fallback to original validation if URL resolution fails
      }
    }

    // URL resolution/validation that matches what the real fetch() call will accept.
    // Browsers resolve relative URLs against window.location; Node.js has no implicit
    // origin, so a relative URL without a configured base URL must fail here with a
    // clear error instead of a cryptic low-level TypeError from the underlying fetch.
    const hasBrowserOrigin =
      typeof window !== "undefined" && typeof window.location !== "undefined";

    if (!hasBrowserOrigin && !regexIsAbsolute.test(finalURL)) {
      console.error("Is required a valid URL", finalURL);
      throw new Error("Is required a valid URL " + finalURL);
    }

    try {
      finalURL = new URL(finalURL, hasBrowserOrigin ? window.location.href : undefined).toString();
    } catch (e) {
      console.error("Is required a valid URL", finalURL);
      throw new Error("Is required a valid URL " + finalURL);
    }

    // Compute the actual payload to be sent in the request body
    const bodyPayload = ["GET", "HEAD", "DELETE"].includes(method)
      ? body
      : (body !== undefined ? body : data);

    const h = this._normalizeHeaders(headers, bodyPayload);

    // GET / HEAD / DELETE → data como querystring
    if (["GET", "HEAD", "DELETE"].includes(method) && data && typeof data === "object") {
      const sp = new URLSearchParams(data);
      const queryString = sp.toString();
      if (queryString) {
        const hashIndex = finalURL.indexOf("#");
        let hash = "";
        let urlWithoutHash = finalURL;

        if (hashIndex !== -1) {
          hash = finalURL.substring(hashIndex);
          urlWithoutHash = finalURL.substring(0, hashIndex);
        }

        const separator = urlWithoutHash.includes("?") ? "&" : "?";
        finalURL = urlWithoutHash + separator + queryString + hash;
      }
    }

    const requestBody = this._createBody(bodyPayload);
    const requestOptions =
      options && typeof options === "object" && !Array.isArray(options) ? options : {};
    const { timeout: optionsTimeout, ...fetchOptions } = requestOptions;
    const timeoutMs =
      timeout !== undefined
        ? timeout
        : (optionsTimeout !== undefined ? optionsTimeout : this._timeoutConfig.timeout);
    const mergedSignal = this._mergeSignals([
      this._abortController ? this._abortController.signal : undefined,
      fetchOptions.signal,
    ]);
    const timeoutState = this._applyTimeout(mergedSignal.signal, timeoutMs);

    const opts = {
      ...fetchOptions,
      method,
      headers: h,
      body: requestBody,
    };

    if (timeoutState.signal) {
      opts.signal = timeoutState.signal;
    }

    if (!opts.dispatcher && this._undiciDispatcher) {
      opts.dispatcher = this._undiciDispatcher;
    }

    let response;
    try {
      const fetchImpl = getFetch();
      response = await fetchImpl(finalURL, opts);

      if (
        typeof window !== "undefined" &&
        this._redirect_in_unauthorized_internal &&
        response.status === 401
      ) {
        window.location.href = this._redirect_in_unauthorized_internal;
      }

      return response;
    } catch (err) {
      const timeoutMessageDuration = this._getTimeoutMessageDuration(err, timeoutMs);

      if (
        timeoutMessageDuration !== undefined &&
        (timeoutState.didTimeout() || NODE_TIMEOUT_ERROR_CODE_TO_CONFIG_KEY[err.code])
      ) {
        this._setErrorMessage(err, `Request timed out after ${timeoutMessageDuration} ms`);
      }

      console.error(err);
      throw err;
    } finally {
      timeoutState.cleanup();
      mergedSignal.cleanup();
    }
  }

  // Simplified Methods

  /**
   * Triggers a read query ("GET" verb). Automatically and transparently serializes `opts.data` using search query strings (e.g., url?foo=bar).
   * @param {{url?: string, data?: any, body?: any, headers?: Object, options?: RequestInit, timeout?: number}} opts - Configuration wrapper object (URL, query params, body payload, local headers, init options and timeout).
   * @returns {Promise<Response>} Original HTTP Promise from the `fetch` API.
   */
  get(opts = {}) {
    return this.request(opts.url, "GET", opts.data, opts.headers, opts.options, opts.body, opts.timeout);
  }

  /** @deprecated Use get() instead. */
  GET(opts = {}) {
    console.warn("DeprecationWarning: uFetch.GET() is deprecated. Use uFetch.get() instead.");
    return this.get(opts);
  }

  /**
   * Triggers a mutation/insertion via an endpoint consuming a "POST" verb.
   * By default, stringifies the `data` (or `body` if provided) to JSON without encoding.
   * @param {{url?: string, data?: any, body?: any, headers?: Object, options?: RequestInit, timeout?: number}} opts
   * @returns {Promise<Response>}
   */
  post(opts = {}) {
    return this.request(
      opts.url,
      "POST",
      opts.data,
      opts.headers,
      opts.options,
      opts.body,
      opts.timeout,
    );
  }

  /** @deprecated Use post() instead. */
  POST(opts = {}) {
    console.warn("DeprecationWarning: uFetch.POST() is deprecated. Use uFetch.post() instead.");
    return this.post(opts);
  }

  /**
   * Replaces existing information by injecting the complete data payload to the router using the "PUT" verb.
   * @param {{url?: string, data?: any, body?: any, headers?: Object, options?: RequestInit, timeout?: number}} opts
   * @returns {Promise<Response>}
   */
  put(opts = {}) {
    return this.request(opts.url, "PUT", opts.data, opts.headers, opts.options, opts.body, opts.timeout);
  }

  /** @deprecated Use put() instead. */
  PUT(opts = {}) {
    console.warn("DeprecationWarning: uFetch.PUT() is deprecated. Use uFetch.put() instead.");
    return this.put(opts);
  }

  /**
   * Controlled backend partial mutation dictated by the "PATCH" verb, modifying fragments.
   * @param {{url?: string, data?: any, body?: any, headers?: Object, options?: RequestInit, timeout?: number}} opts
   * @returns {Promise<Response>}
   */
  patch(opts = {}) {
    return this.request(
      opts.url,
      "PATCH",
      opts.data,
      opts.headers,
      opts.options,
      opts.body,
      opts.timeout,
    );
  }

  /** @deprecated Use patch() instead. */
  PATCH(opts = {}) {
    console.warn("DeprecationWarning: uFetch.PATCH() is deprecated. Use uFetch.patch() instead.");
    return this.patch(opts);
  }

  /**
   * Orders to clear / destroy a resource tuple pointed at by `url` by sending a "DELETE" verb.
   * @param {{url?: string, data?: any, body?: any, headers?: Object, options?: RequestInit, timeout?: number}} opts
   * @returns {Promise<Response>}
   */
  delete(opts = {}) {
    return this.request(
      opts.url,
      "DELETE",
      opts.data,
      opts.headers,
      opts.options,
      opts.body,
      opts.timeout,
    );
  }

  /** @deprecated Use delete() instead. */
  DELETE(opts = {}) {
    console.warn("DeprecationWarning: uFetch.DELETE() is deprecated. Use uFetch.delete() instead.");
    return this.delete(opts);
  }

  /**
   * Triggers a safe/idempotent read query via the "QUERY" verb (draft IETF method), sending
   * `opts.data` (or `opts.body`) as a JSON request body instead of a URL querystring — useful
   * for read operations whose filter payload is too complex or large for a query string.
   * Note: "QUERY" is not yet a standardized/universally supported HTTP method — intermediate
   * proxies, load balancers, or the target server may reject or rewrite it.
   * @param {{url?: string, data?: any, body?: any, headers?: Object, options?: RequestInit, timeout?: number}} opts
   * @returns {Promise<Response>}
   */
  query(opts = {}) {
    return this.request(opts.url, "QUERY", opts.data, opts.headers, opts.options, opts.body, opts.timeout);
  }

  /**
   * Processes a list of payloads in parallel batches with a configured concurrency limit (Pool).
   * Every item in the batch shares the exact same `method`, `headers`, `options` and `timeout` —
   * there is no per-item override. Highly optimized for AI Agents and bulk data processing.
   *
   * NOTE: The signature batch(url, method, items, headers, options, config) with positional arguments
   * is deprecated and will now throw an exception. Use the single configuration object instead.
   * If you explicitly need to use positional parameters, use the batch_old() method.
   *
   * NOTE ON URL PARAMETER:
   * The `url` field in the batch input parameters is optional. It should only be used if the URL was not passed to the class constructor, or if you explicitly want to override/change the URL defined in the class constructor.
   *
   * SPECIFICATIONS FOR THE 'items' PROPERTY (CRITICAL FOR AI AGENTS):
   * The 'items' parameter accepts exactly one of these two shapes:
   * 1. A PLAIN ARRAY (default/most common): each element is sent verbatim as the `data` argument to
   *    `request()` for every item — the same behavior as calling `request(url, method, element, headers, options, undefined, timeout)`.
   *    Elements are never inspected or partially extracted, regardless of what keys they contain.
   * 2. AN OBJECT WRAPPER `{ data: [...] }` OR `{ body: [...] }`: chooses, for the WHOLE batch, whether the
   *    list is sent through the `data` argument (query string on GET/HEAD/DELETE, JSON body otherwise) or
   *    forced through the `body` argument (always sent as the HTTP body, mirroring `request()`'s own
   *    `data` vs `body` distinction). The array inside `data`/`body` is the actual list of payloads; each
   *    element is still sent verbatim, with no per-item interpretation.
   * `url`, `method`, `headers`, `options` and `timeout` always come from the top-level `opts` and apply
   * identically to every item. If you need a different URL/method/timeout for a specific payload, use
   * `Promise.all` with individual `request()`/`get()`/`post()` calls instead of `batch()`.
   *
   * @param {Object} opts - Configuration options for the batch request.
   * @param {string} [opts.url] - (Optional) Base URL for requests (fallback). Should only be used when no URL was passed in the constructor, or if you explicitly want to change the URL defined in the constructor.
   * @param {string} [opts.method="GET"] - HTTP verb applied to every item.
   * @param {Array<any>|{data?: Array<any>, body?: Array<any>}} opts.items - The payload list: a plain array (sent as `data`), or `{ data: [...] }` / `{ body: [...] }` to choose how the whole batch is sent.
   * @param {Object} [opts.headers={}] - Headers applied to every item.
  * @param {Object} [opts.options={}] - Fetch options (RequestInit) applied to every item.
  * @param {number} [opts.timeout] - Timeout applied to every request in the batch.
   * @param {Object} [opts.config={}] - Batch settings.
   * @param {number} [opts.config.concurrency=5] - Parallel worker limit.
   * @param {Function} [opts.config.onProgress] - Callback invoked after each request resolution: (info) => void.
   * @param {Function} [opts.config.responseParser] - (Optional) Custom extractor function for the response payload: async (response) => data.
   * @param {boolean} [opts.config.includeResponse=false] - (Optional) If true, includes the raw Fetch 'response' object in the result descriptor.
   * @returns {Promise<Array<{isError: boolean, httpCode: number|null, data?: any, response?: Response, error?: any}>>} Array of result descriptors (ordered).
   * Each descriptor sets `isError` to `true` when the item failed at the network level (request/parse threw)
   * OR when the server answered with an HTTP error status (>= 400). For HTTP error responses the body is
   * still parsed into `data` and `error` is an `Error` describing the status; for transport failures `data`
   * is omitted and `error` is the original exception.
   */
  async batch(opts = {}) {
    if (arguments.length > 1) {
      throw new Error(
        "uFetch.batch() now only accepts a single configuration object parameter. " +
        "If you need to use the deprecated positional arguments signature, please use uFetch.batch_old() instead."
      );
    }

    if (typeof opts !== "object" || opts === null || Array.isArray(opts)) {
      throw new Error(
        "uFetch.batch() expects a single configuration object containing options (e.g., { url, method, items, headers, options, config }). " +
        "To use the deprecated positional arguments signature, please use uFetch.batch_old() instead."
      );
    }

    if (!opts.hasOwnProperty("items")) {
      throw new Error("uFetch.batch() requires the 'items' parameter inside the configuration object.");
    }

    const {
      url,
      method: reqMethod = "GET",
      items: reqItems = [],
      headers: reqHeaders = {},
      options: reqOptions = {},
      timeout: reqTimeout = undefined,
      config: reqConfig = {},
    } = opts;

    const {
      concurrency = 5,
      onProgress,
      responseParser,
      includeResponse = false,
    } = reqConfig;

    const { list: reqItemsList, sendAs } = resolveBatchItems(reqItems);

    const total = reqItemsList.length;
    const results = new Array(total);
    let currentIndex = 0;
    let completed = 0;

    const worker = async () => {
      while (currentIndex < total) {
        const index = currentIndex++;
        const item = reqItemsList[index];
        let resultPayload;
        let response = null;

        try {
          response = await this.request(
            url,
            reqMethod,
            sendAs === "data" ? item : undefined,
            reqHeaders,
            reqOptions,
            sendAs === "body" ? item : undefined,
            reqTimeout
          );

          const isHttpError = response.status >= 400;
          const parser = responseParser || defaultResponseParser;
          const parsedData = await parser(response);

          resultPayload = {
            isError: isHttpError,
            httpCode: response.status,
            data: parsedData,
          };

          if (isHttpError) {
            const statusText = response.statusText ? ` ${response.statusText}` : "";
            resultPayload.error = new Error(`HTTP ${response.status}${statusText}`);
          }

          if (includeResponse) {
            resultPayload.response = response;
          }
        } catch (error) {
          resultPayload = {
            isError: true,
            error: error,
            httpCode: response ? response.status : null,
          };
          if (includeResponse && response) {
            resultPayload.response = response;
          }
        }

        results[index] = resultPayload;
        completed++;

        if (typeof onProgress === "function") {
          onProgress({
            completed,
            total,
            item,
            isError: resultPayload.isError,
            httpCode: resultPayload.httpCode,
            error: resultPayload.error,
            response: response,
            data: resultPayload.data,
          });
        }
      }
    };

    const workers = [];
    const safeConcurrency = Math.max(1, Math.floor(Number(concurrency) || 1));
    const poolSize = Math.min(safeConcurrency, total);
    for (let i = 0; i < poolSize; i++) {
      workers.push(worker());
    }

    await Promise.all(workers);
    return results;
  }

  /**
   * Processes an array of items in parallel batches using the legacy positional arguments signature.
   * Internally maps parameters and calls the modern batch() method.
   * 
   * @deprecated Use batch() instead.
   * @param {string} [url=undefined]
   * @param {string} [method="GET"]
   * @param {Array<any>} [items=[]]
   * @param {Object} [headers={}]
   * @param {Object} [options={}]
   * @param {Object} [config={}]
   * @returns {Promise<Array<{isError: boolean, httpCode: number|null, response?: Response, error?: any}>>}
   */
  async batch_old(
    url = undefined,
    method = "GET",
    items = [],
    headers = {},
    options = {},
    config = {}
  ) {
    return this.batch({
      url,
      method,
      items,
      headers,
      options,
      config,
    });
  }
}

module.exports = uFetch;
